//! Gen9 golden render state, built from named commands.
//!
//! Linux runs a "null" 3D state batch once on Gen9's render engine, records
//! the context image the hardware saves as the engine's default state, and
//! starts every later context from that image instead of an unrestored one
//! (MIT `gt/intel_renderstate.c`, `gt/intel_gt.c::__engines_record_defaults`).
//! Linux carries the batch as a table generated by IGT's
//! `tools/null_state_gen` (`gt/gen9_renderstate.c`). This module emits the
//! same command stream from opcodes and fields instead: every 3D state the
//! context image saves gets a defined value before the first save.
//!
//! The batch is self-contained. STATE_BASE_ADDRESS points the general,
//! surface, dynamic and instruction bases at the batch itself, so the state
//! pointers below are offsets into the same page.

use alloc::vec;
use alloc::vec::Vec;

/// Batch size: commands, then the indirect state at [`CC_STATE`] onwards.
pub(crate) const NULL_STATE_BYTES: usize = 0xf00;
/// COLOR_CALC_STATE: the blend constant colour is (1, 1, 1, 1).
const CC_STATE: u32 = 0xe00;
/// BLEND_STATE: all zero.
const BLEND_STATE: u32 = 0xe40;
/// CC_VIEWPORT: min/max depth zero.
const CC_VIEWPORT: u32 = 0xea0;
/// SF_CLIP_VIEWPORT: all zero.
const SF_CLIP_VIEWPORT: u32 = 0xec0;

const MI_BATCH_BUFFER_END: u32 = 0x0500_0000;
const ONE_F32: u32 = 0x3f80_0000;

/// A GFXPIPE header: command type 3, `subtype`, `opcode`, `sub_opcode`, and
/// the DWord length (total dwords minus two).
const fn gfx(subtype: u32, opcode: u32, sub_opcode: u32, dwords: u32) -> u32 {
    3 << 29 | subtype << 27 | opcode << 24 | sub_opcode << 16 | (dwords - 2)
}

/// 3DSTATE (pipelined, opcode 0) and 3DSTATE (non-pipelined, opcode 1).
const fn state(sub_opcode: u32, dwords: u32) -> u32 {
    gfx(3, 0, sub_opcode, dwords)
}
const fn state1(sub_opcode: u32, dwords: u32) -> u32 {
    gfx(3, 1, sub_opcode, dwords)
}

// 3DSTATE_* sub-opcodes under opcode 0.
const CLEAR_PARAMS: u32 = 0x04;
const DEPTH_BUFFER: u32 = 0x05;
const STENCIL_BUFFER: u32 = 0x06;
const HIER_DEPTH_BUFFER: u32 = 0x07;
const VERTEX_BUFFERS: u32 = 0x08;
const VERTEX_ELEMENTS: u32 = 0x09;
const INDEX_BUFFER: u32 = 0x0a;
const VF: u32 = 0x0c;
const MULTISAMPLE: u32 = 0x0d;
const CC_STATE_POINTERS: u32 = 0x0e;
const SCISSOR_STATE_POINTERS: u32 = 0x0f;
const VS: u32 = 0x10;
const GS: u32 = 0x11;
const CLIP: u32 = 0x12;
const SF: u32 = 0x13;
const WM: u32 = 0x14;
const CONSTANT_VS: u32 = 0x15;
const CONSTANT_GS: u32 = 0x16;
const CONSTANT_PS: u32 = 0x17;
const CONSTANT_HS: u32 = 0x19;
const CONSTANT_DS: u32 = 0x1a;
const HS: u32 = 0x1b;
const TE: u32 = 0x1c;
const DS: u32 = 0x1d;
const STREAMOUT: u32 = 0x1e;
const SBE: u32 = 0x1f;
const PS: u32 = 0x20;
const VIEWPORT_STATE_POINTERS_SF_CLIP: u32 = 0x21;
const VIEWPORT_STATE_POINTERS_CC: u32 = 0x23;
const BLEND_STATE_POINTERS: u32 = 0x24;
/// BINDING_TABLE_POINTERS_{VS,HS,DS,GS,PS}.
const BINDING_TABLE_POINTERS: [u32; 5] = [0x26, 0x27, 0x28, 0x29, 0x2a];
/// SAMPLER_STATE_POINTERS_{VS,HS,DS,GS,PS}.
const SAMPLER_STATE_POINTERS: [u32; 5] = [0x2b, 0x2c, 0x2d, 0x2e, 0x2f];
/// URB_{VS,HS,DS,GS}.
const URB: [u32; 4] = [0x30, 0x31, 0x32, 0x33];
const VF_INSTANCING: u32 = 0x49;
const VF_SGVS: u32 = 0x4a;
const VF_TOPOLOGY: u32 = 0x4b;
const PS_BLEND: u32 = 0x4d;
const PS_EXTRA: u32 = 0x4f;
const RASTER: u32 = 0x50;
const SBE_SWIZ: u32 = 0x51;
const WM_HZ_OP: u32 = 0x52;
const COMPONENT_PACKING: u32 = 0x55;

// 3DSTATE_* sub-opcodes under opcode 1.
const DRAWING_RECTANGLE: u32 = 0x00;
const SAMPLER_PALETTE_LOAD0: u32 = 0x02;
const CHROMA_KEY: u32 = 0x04;
const POLY_STIPPLE_OFFSET: u32 = 0x06;
const POLY_STIPPLE_PATTERN: u32 = 0x07;
const LINE_STIPPLE: u32 = 0x08;
const AA_LINE_PARAMETERS: u32 = 0x0a;
const SAMPLER_PALETTE_LOAD1: u32 = 0x0c;
const MONOFILTER_SIZE: u32 = 0x11;
/// PUSH_CONSTANT_ALLOC_{VS,HS,DS,GS,PS}.
const PUSH_CONSTANT_ALLOC: [u32; 5] = [0x12, 0x13, 0x14, 0x15, 0x16];
const SO_DECL_LIST: u32 = 0x17;
const SO_BUFFER: u32 = 0x18;
const BINDING_TABLE_POOL_ALLOC: u32 = 0x19;
const GATHER_POOL_ALLOC: u32 = 0x1a;
const DX9_CONSTANTBUFFER_POOL_ALLOC: u32 = 0x1b;

const PIPE_CONTROL: u32 = gfx(3, 2, 0, 6);
/// PIPELINE_SELECT with the Gen9 selection mask (bits 9:8) and 3D (0).
const PIPELINE_SELECT_3D: u32 = gfx(1, 1, 4, 2) | 0x300;
/// 3DSTATE_VF_STATISTICS (single dword), statistics enabled.
const VF_STATISTICS_ENABLE: u32 = gfx(1, 0, 0x0b, 2) | 1;
const STATE_BASE_ADDRESS: u32 = gfx(0, 1, 1, 19);
const STATE_SIP: u32 = gfx(0, 1, 2, 3);
const PRIMITIVE: u32 = gfx(3, 3, 0, 7);
/// 3DPRIM_TRILIST.
const TRILIST: u32 = 4;

struct Batch(Vec<u32>);

impl Batch {
    /// Emit `header` followed by its payload, zero except `fields`
    /// (`(dword index, value)`, index 1 being the first payload dword).
    fn command(&mut self, header: u32, dwords: usize, fields: &[(usize, u32)]) {
        let start = self.0.len();
        self.0.push(header);
        self.0.resize(start + dwords, 0);
        for &(index, value) in fields {
            debug_assert!((1..dwords).contains(&index));
            self.0[start + index] = value;
        }
    }

    fn zeroed(&mut self, header: u32, dwords: usize) {
        self.command(header, dwords, &[]);
    }
}

/// The Gen9 null render state batch, relocated to GGTT address `base` (page
/// aligned, below 4 GiB in practice; the upper dwords carry the rest). The
/// caller runs it once on a restore-inhibited render context and keeps the
/// saved image.
pub(crate) fn gen9_null_state(base: u64, pooled_eu: bool) -> Vec<u32> {
    // The general, surface, dynamic and instruction bases all address this
    // batch (bit 0: modify enable); the indirect object base stays at zero.
    let reloc = base + 1;
    let mut b = Batch(Vec::with_capacity(NULL_STATE_BYTES / 4));
    // A PIPE_CONTROL with no flush or post-sync, GGTT address space.
    b.command(PIPE_CONTROL, 6, &[(1, 1 << 24)]);
    b.0.push(PIPELINE_SELECT_3D);
    // Legacy diamond-line rasterization.
    b.command(state(WM, 2), 2, &[(1, 1 << 26)]);
    // Single program flow; no kernel, so nothing dispatches.
    b.command(state(PS, 12), 12, &[(3, 1 << 31)]);
    // Triangle-fan provoking vertex 1, point width 1.0 from state.
    b.command(state(SF, 4), 4, &[(3, 0x0200_1808)]);
    b.zeroed(state(SBE, 6), 6);
    b.zeroed(state(SBE_SWIZ, 11), 11);
    // Alternate floating-point mode; no kernel.
    b.command(state(VS, 9), 9, &[(3, 1 << 16)]);
    b.command(state(HS, 9), 9, &[(7, 0x800)]);
    b.zeroed(state(GS, 10), 10);
    b.zeroed(state(STREAMOUT, 5), 5);
    b.zeroed(state(DS, 11), 11);
    b.zeroed(state(CLIP, 4), 4);
    b.zeroed(state(RASTER, 5), 5);
    b.zeroed(state(TE, 4), 4);
    b.zeroed(state(VF, 2), 2);
    b.zeroed(state(WM_HZ_OP, 5), 5);
    // URB: 64 VS entries of one 512-bit row from 32 KiB (start 4, in 8 KiB
    // units); HS, DS and GS get no entries, starting at 15.
    b.command(state(URB[0], 2), 2, &[(1, 4 << 25 | 1 << 16 | 64)]);
    for sub in &URB[1..] {
        b.command(state(*sub, 2), 2, &[(1, 15 << 25)]);
    }
    b.zeroed(state1(BINDING_TABLE_POOL_ALLOC, 4), 4);
    b.zeroed(state1(GATHER_POOL_ALLOC, 4), 4);
    b.zeroed(state1(DX9_CONSTANTBUFFER_POOL_ALLOC, 4), 4);
    for sub in PUSH_CONSTANT_ALLOC {
        b.zeroed(state1(sub, 2), 2);
    }
    for sub in [
        CONSTANT_VS,
        CONSTANT_HS,
        CONSTANT_DS,
        CONSTANT_GS,
        CONSTANT_PS,
    ] {
        b.zeroed(state(sub, 11), 11);
    }
    b.zeroed(state(VF_INSTANCING, 3), 3);
    b.zeroed(state(VF_SGVS, 2), 2);
    b.command(state(VF_TOPOLOGY, 2), 2, &[(1, TRILIST)]);
    // 128 zero declarations for stream 0 (a nine-bit length field).
    b.command(state1(SO_DECL_LIST, 259), 259, &[(2, 128)]);
    for index in 0..4 {
        b.command(state1(SO_BUFFER, 8), 8, &[(1, index << 29)]);
    }
    let (low, high) = (reloc as u32, (reloc >> 32) as u32);
    b.command(
        STATE_BASE_ADDRESS,
        19,
        &[
            (1, low),  // general state base
            (2, high), //
            (4, low),  // surface state base
            (5, high), //
            (6, low),  // dynamic state base
            (7, high), //
            (8, 1),    // indirect object base: zero, modify enable
            (10, low), // instruction base
            (11, high),
            // Buffer sizes: one page each (indirect object: zero), with
            // modify enable.
            (12, 0x1001),
            (13, 0x1001),
            (14, 1),
            (15, 0x1001),
        ],
    );
    b.zeroed(STATE_SIP, 3);
    b.zeroed(state1(DRAWING_RECTANGLE, 4), 4);
    b.zeroed(state(DEPTH_BUFFER, 8), 8);
    for index in 0..4 {
        b.command(state1(CHROMA_KEY, 4), 4, &[(1, index << 30)]);
    }
    b.zeroed(state1(LINE_STIPPLE, 3), 3);
    b.zeroed(state1(AA_LINE_PARAMETERS, 3), 3);
    b.zeroed(state(STENCIL_BUFFER, 5), 5);
    b.zeroed(state(HIER_DEPTH_BUFFER, 5), 5);
    b.zeroed(state(CLEAR_PARAMS, 3), 3);
    b.zeroed(state1(MONOFILTER_SIZE, 2), 2);
    b.zeroed(state(MULTISAMPLE, 2), 2);
    b.zeroed(state1(POLY_STIPPLE_OFFSET, 2), 2);
    b.zeroed(state1(POLY_STIPPLE_PATTERN, 33), 33);
    b.zeroed(state1(SAMPLER_PALETTE_LOAD0, 17), 17);
    b.zeroed(state1(SAMPLER_PALETTE_LOAD1, 17), 17);
    b.zeroed(state(INDEX_BUFFER, 5), 5);
    // All 33 vertex buffers: address modify enable, null address and size.
    let buffers: Vec<(usize, u32)> = (0..33u32)
        .map(|index| (1 + index as usize * 4, index << 26 | 1 << 14))
        .collect();
    b.command(state(VERTEX_BUFFERS, 133), 133, &buffers);
    // Element 0 valid, buffer 0, storing zero in all four components; the
    // other 33 element slots stay invalid.
    b.command(
        state(VERTEX_ELEMENTS, 69),
        69,
        &[(1, 1 << 25), (2, 2 << 28 | 2 << 24 | 2 << 20 | 2 << 16)],
    );
    // Element 0 enables all four components.
    b.command(state(COMPONENT_PACKING, 5), 5, &[(1, 0xf)]);
    b.0.push(VF_STATISTICS_ENABLE);
    // Pointers into dynamic state; bit 0 marks the CC and blend pointers
    // valid.
    b.command(state(CC_STATE_POINTERS, 2), 2, &[(1, CC_STATE | 1)]);
    b.command(state(BLEND_STATE_POINTERS, 2), 2, &[(1, BLEND_STATE | 1)]);
    // Pixel shader valid, attribute enable.
    b.command(state(PS_EXTRA, 2), 2, &[(1, 1 << 31 | 1 << 8)]);
    // Has writeable render target.
    b.command(state(PS_BLEND, 2), 2, &[(1, 1 << 30)]);
    for sub in SAMPLER_STATE_POINTERS {
        b.zeroed(state(sub, 2), 2);
    }
    b.zeroed(state(SCISSOR_STATE_POINTERS, 2), 2);
    b.command(state(VIEWPORT_STATE_POINTERS_CC, 2), 2, &[(1, CC_VIEWPORT)]);
    b.command(
        state(VIEWPORT_STATE_POINTERS_SF_CLIP, 2),
        2,
        &[(1, SF_CLIP_VIEWPORT)],
    );
    for sub in BINDING_TABLE_POINTERS {
        b.zeroed(state(sub, 2), 2);
    }
    // One triangle-list vertex, one instance: nothing is rasterized.
    b.command(PRIMITIVE, 7, &[(1, TRILIST), (2, 1), (4, 1)]);
    // render_state_setup's aux batch on a pooled-EU part: the 3x6 pool
    // configuration, which the hardware narrows to the fused subslices.
    // Linux starts it as a second batch at `aux_offset` in the same request;
    // here it follows the primitive in this batch, the same command order.
    if pooled_eu {
        b.0.extend_from_slice(&[
            crate::intel_gpu_rcs::GEN9_MEDIA_POOL_STATE,
            crate::intel_gpu_rcs::GEN9_MEDIA_POOL_ENABLE,
            0x0077_7000,
            0,
            0,
            0,
        ]);
    }
    b.0.push(MI_BATCH_BUFFER_END);
    debug_assert!(b.0.len() * 4 <= CC_STATE as usize);
    let mut words = b.0;
    words.resize(NULL_STATE_BYTES / 4, 0);
    // COLOR_CALC_STATE dwords 2-5: blend constant colour.
    let cc = CC_STATE as usize / 4;
    words[cc + 2..cc + 6].copy_from_slice(&[ONE_F32; 4]);
    words
}

/// An empty batch: the context workarounds alone are recorded (Linux has no
/// null render state for Gen11).
pub(crate) fn empty_state() -> Vec<u32> {
    vec![MI_BATCH_BUFFER_END, 0]
}

#[cfg(any(test, feature = "kernel-test"))]
pub mod tests {
    use super::*;
    use narf_kernel_test::{kernel_test_in, kt_assert, kt_assert_eq, TestResult};

    /// Command length in dwords for the Gen9 commands this batch emits.
    fn length(word: u32) -> usize {
        match word >> 16 {
            0x6904 | 0x680b => 1,
            0x7917 => (word & 0x1ff) as usize + 2,
            _ => (word & 0xff) as usize + 2,
        }
    }

    fn smoke_gen9_null_state_layout() -> TestResult {
        let base = 0x0012_3000;
        let words = gen9_null_state(base, false);
        kt_assert_eq!(words.len() * 4, NULL_STATE_BYTES);
        // A pooled-EU part appends the media pool state before the end,
        // still below the indirect state; nothing else moves.
        let pooled = gen9_null_state(base, true);
        kt_assert_eq!(pooled.len(), words.len());
        kt_assert_eq!(&pooled[..885], &words[..885]);
        kt_assert_eq!(
            &pooled[885..892],
            &[
                0x7005_0004,
                1 << 31,
                0x0077_7000,
                0,
                0,
                0,
                MI_BATCH_BUFFER_END
            ]
        );
        kt_assert_eq!(&pooled[896..], &words[896..]);
        // Walk the command stream: it must parse to MI_BATCH_BUFFER_END
        // before the indirect state, ending in the one-vertex 3DPRIMITIVE.
        let mut at = 0;
        let mut headers = Vec::new();
        while words[at] != MI_BATCH_BUFFER_END {
            headers.push(words[at] >> 16);
            at += length(words[at]);
            kt_assert!(at * 4 < CC_STATE as usize);
        }
        kt_assert_eq!(at, 885);
        kt_assert_eq!(headers.first(), Some(&0x7a00));
        kt_assert_eq!(headers.get(1), Some(&0x6904));
        kt_assert_eq!(headers.last(), Some(&0x7b00));
        kt_assert_eq!(headers.len(), 84);
        kt_assert_eq!(&words[at - 6..at], &[TRILIST, 1, 0, 1, 0, 0]);
        // STATE_BASE_ADDRESS relocations point at the batch itself.
        let Some(sba) = words.iter().position(|w| *w == 0x6101_0011) else {
            return TestResult::Fail("STATE_BASE_ADDRESS missing");
        };
        for dword in [1, 4, 6, 10] {
            kt_assert_eq!(words[sba + dword], base as u32 + 1);
            kt_assert_eq!(words[sba + dword + 1], 0);
        }
        kt_assert_eq!(&words[sba + 12..sba + 16], &[0x1001, 0x1001, 1, 0x1001]);
        // CC state: blend constant (1, 1, 1, 1); everything else zero.
        let tail: Vec<_> = words[at + 1..]
            .iter()
            .enumerate()
            .filter(|(_, w)| **w != 0)
            .map(|(i, _)| (at + 1 + i) * 4)
            .collect();
        kt_assert_eq!(tail, alloc::vec![0xe08, 0xe0c, 0xe10, 0xe14]);
        TestResult::Pass
    }

    kernel_test_in!(
        "drivers/gpu/intel_gpu_renderstate",
        smoke_gen9_null_state_layout
    );
}
